**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <cmath>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("punkty.txt");
    int n;
    plik >> n;
    int px[100], py[100];
    for (int i = 0; i < n; i++) plik >> px[i] >> py[i];
    double minD = 1e18, maxD = -1;
    int mi1 = 0, mi2 = 1, ma1 = 0, ma2 = 1;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            double dx = px[j] - px[i];
            double dy = py[j] - py[i];
            double d = sqrt(dx * dx + dy * dy);
            if (d < minD) { minD = d; mi1 = i; mi2 = j; }
            if (d > maxD) { maxD = d; ma1 = i; ma2 = j; }
        }
    }
    cout << fixed << setprecision(2);
    cout << "Najblizsza para: (" << px[mi1] << "," << py[mi1] << ")-(" << px[mi2] << "," << py[mi2] << "), odleglosc = " << minD << endl;
    cout << "Najdalsza para: (" << px[ma1] << "," << py[ma1] << ")-(" << px[ma2] << "," << py[ma2] << "), odleglosc = " << maxD << endl;
    return 0;
}
```

**Wyjasnienie**: Sprawdzamy wszystkie pary punktow (podwojna petla z i<j), sledzimy minimum i maksimum odleglosci. Zlozonosc O(n^2) jest wystarczajaca dla malych zbiorow.

